class Solution:
    def isShuffle(self, a: str, b: str) -> bool:
        if len(a) != len(b):
            return False
        count = {}
        for ch in a:
            count[ch] = count.get(ch, 0) + 1
        for ch in b:
            left = count.get(ch, 0)
            if left == 0:
                return False
            count[ch] = left - 1
        return True

