        pass

ctci-run-length-shrink.solution:
class Solution:
    def shrink(self, log: str) -> str:
        parts = []
        i, n = 0, len(log)
        while i < n:
            j = i
            while j < n and log[j] == log[i]:
                j += 1
            parts.append(log[i])
            parts.append(str(j - i))
            i = j
        packed = "".join(parts)
        return packed if len(packed) < len(log) else log

