ctci-one-typo-apart.solution:
class Solution:
    def oneTypoApart(self, a: str, b: str) -> bool:
        if len(a) > len(b):
            a, b = b, a
        if len(b) - len(a) > 1:
            return False
        i = j = 0
        used = False
        while i < len(a) and j < len(b):
            if a[i] == b[j]:
                i += 1
                j += 1
                continue
            if used:
                return False
            used = True
            if len(a) == len(b):
                i += 1
            j += 1
        return True

