ctci-blackout-rows-cols.solution:
class Solution:
    def blackout(self, grid: List[List[int]]) -> None:
        m, n = len(grid), len(grid[0])
        first_row = any(grid[0][c] == 0 for c in range(n))
        first_col = any(grid[r][0] == 0 for r in range(m))
        for r in range(1, m):
            for c in range(1, n):
                if grid[r][c] == 0:
                    grid[r][0] = 0
                    grid[0][c] = 0
        for r in range(1, m):
            for c in range(1, n):
                if grid[r][0] == 0 or grid[0][c] == 0:
                    grid[r][c] = 0
        if first_row:
            for c in range(n):
                grid[0][c] = 0
        if first_col:
            for r in range(m):
                grid[r][0] = 0

