class Solution:
    def dropRepeats(self, head: Optional[ListNode]) -> Optional[ListNode]:
        seen = set()
        prev, cur = None, head
        while cur:
            if cur.val in seen:
                prev.next = cur.next
            else:
                seen.add(cur.val)
                prev = cur
            cur = cur.next
        return head

