ctci-pivot-split-list.solution:
class Solution:
    def pivotSplit(self, head: Optional[ListNode], pivot: int) -> Optional[ListNode]:
        small_head = small = ListNode()
        big_head = big = ListNode()
        cur = head
        while cur:
            if cur.val < pivot:
                small.next = cur
                small = cur
            else:
                big.next = cur
                big = cur
            cur = cur.next
        big.next = None
        small.next = big_head.next
        return small_head.next

