class Solution:
    def loopEntry(self, nxt: List[int]) -> int:
        slow = fast = 0
        while True:
            if fast == -1 or nxt[fast] == -1:
                return -1
            slow = nxt[slow]
            fast = nxt[nxt[fast]]
            if slow == fast:
                break
        slow = 0
        while slow != fast:
            slow = nxt[slow]
            fast = nxt[fast]
        return slow

