ctci-relay-queue.solution:
class RelayQueue:
    def __init__(self):
        self.inbox = []
        self.outbox = []

    def _shift(self):
        if not self.outbox:
            while self.inbox:
                self.outbox.append(self.inbox.pop())

    def enqueue(self, x: int) -> None:
        self.inbox.append(x)

    def dequeue(self) -> int:
        self._shift()
        return self.outbox.pop() if self.outbox else -1

    def front(self) -> int:
        self._shift()
        return self.outbox[-1] if self.outbox else -1

    def size(self) -> int:
        return len(self.inbox) + len(self.outbox)

