ctci-sort-with-spare-stack.solution:
class Solution:
    def sortStack(self, stack: List[int]) -> List[int]:
        spare = []
        while stack:
            crate = stack.pop()
            while spare and spare[-1] > crate:
                stack.append(spare.pop())
            spare.append(crate)
        while spare:
            stack.append(spare.pop())
        return stack

