ctci-route-exists.solution:
class Solution:
    def hasRoute(self, n: int, streets: List[List[int]], src: int, dst: int) -> bool:
        out = [[] for _ in range(n)]
        for a, b in streets:
            out[a].append(b)
        seen = [False] * n
        seen[src] = True
        queue = collections.deque([src])
        while queue:
            node = queue.popleft()
            if node == dst:
                return True
            for nxt in out[node]:
                if not seen[nxt]:
                    seen[nxt] = True
                    queue.append(nxt)
        return False

