class Solution:
    def buildBalanced(self, scores: List[int]) -> Optional[TreeNode]:
        def build(lo, hi):
            if lo > hi:
                return None
            mid = (lo + hi) // 2
            return TreeNode(scores[mid], build(lo, mid - 1), build(mid + 1, hi))
        return build(0, len(scores) - 1)

