ctci-compile-order.solution:
class Solution:
    def compileOrder(self, n: int, needs: List[List[int]]) -> List[int]:
        after = [[] for _ in range(n)]
        waiting = [0] * n
        for a, b in needs:
            after[a].append(b)
            waiting[b] += 1
        ready = collections.deque(i for i in range(n) if waiting[i] == 0)
        order = []
        while ready:
            m = ready.popleft()
            order.append(m)
            for nxt in after[m]:
                waiting[nxt] -= 1
                if waiting[nxt] == 0:
                    ready.append(nxt)
        return order if len(order) == n else []

ctci-compile-order.checker:
def check(args, got, expected):
    n, needs = args
    if expected == []:
        return got == []
    if not isinstance(got, list) or sorted(got) != list(range(n)):
        return False
    pos = {m: i for i, m in enumerate(got)}
    return all(pos[a] < pos[b] for a, b in needs)

