ctci-longest-ones-one-flip.solution:
class Solution:
    def bestRun(self, x: int) -> int:
        if x == 0xFFFFFFFF:
            return 32
        current = previous = 0
        best = 1
        for _ in range(32):
            if x & 1:
                current += 1
            else:
                previous = current if (x & 2) else 0
                current = 0
            best = max(best, previous + current + 1)
            x >>= 1
        return best

