ctci-binary-fraction.solution:
class Solution:
    def fractionBits(self, num: int, den: int) -> str:
        digits = []
        while num:
            if len(digits) == 32:
                return "ERROR"
            num *= 2
            if num >= den:
                digits.append("1")
                num -= den
            else:
                digits.append("0")
        return "0." + "".join(digits)

