ctci-smooth-number-k.solution:
class Solution:
    def kthSmooth(self, k: int, primes: List[int]) -> int:
        seq = [1]
        at = [0] * len(primes)
        while len(seq) < k:
            heads = [seq[at[j]] * p for j, p in enumerate(primes)]
            nxt = min(heads)
            seq.append(nxt)
            for j, value in enumerate(heads):
                if value == nxt:
                    at[j] += 1
        return seq[k - 1]

