ctci-dice-sum-probability.solution:
class Solution:
    def diceChance(self, n: int, total: int) -> List[int]:
        ways = [1] + [0] * total
        for _ in range(n):
            nxt = [0] * (total + 1)
            for s in range(total + 1):
                if ways[s]:
                    for face in range(1, 7):
                        if s + face <= total:
                            nxt[s + face] += ways[s]
            ways = nxt
        num, den = ways[total], 6 ** n
        if num == 0:
            return [0, 1]
        g = math.gcd(num, den)
        return [num // g, den // g]

