ctci-jug-pour.solution:
class Solution:
    def minPours(self, a: int, b: int, goal: int) -> int:
        start = (0, 0)
        dist = {start: 0}
        queue = collections.deque([start])
        while queue:
            x, y = queue.popleft()
            if x == goal or y == goal:
                return dist[(x, y)]
            to_b = min(x, b - y)
            to_a = min(y, a - x)
            for state in ((a, y), (x, b), (0, y), (x, 0), (x - to_b, y + to_b), (x + to_a, y - to_a)):
                if state not in dist:
                    dist[state] = dist[(x, y)] + 1
                    queue.append(state)
        return -1

