class Solution:
    def handValue(self, cards: List[str]) -> int:
        total = aces = 0
        for card in cards:
            if card == "A":
                aces += 1
                total += 1
            elif card in ("J", "Q", "K"):
                total += 10
            else:
                total += int(card)
        if aces and total + 10 <= 21:
            total += 10
        return total

