ctci-flip-discs.solution:
class Solution:
    def placeDisc(self, board: List[str], row: int, col: int, colour: str) -> List[str]:
        n = len(board)
        grid = [list(line) for line in board]
        if grid[row][col] != ".":
            return board
        other = "W" if colour == "B" else "B"
        flips = []
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                r, c = row + dr, col + dc
                line = []
                while 0 <= r < n and 0 <= c < n and grid[r][c] == other:
                    line.append((r, c))
                    r += dr
                    c += dc
                if line and 0 <= r < n and 0 <= c < n and grid[r][c] == colour:
                    flips.extend(line)
        if not flips:
            return board
        grid[row][col] = colour
        for r, c in flips:
            grid[r][c] = colour
        return ["".join(line) for line in grid]

