ctci-mini-fs.solution:
class MiniFS:
    def __init__(self):
        self.root = {}

    def _walk(self, parts):
        node = self.root
        for name in parts:
            if not isinstance(node, dict) or name not in node:
                return None
            node = node[name]
        return node

    def _create(self, path, value):
        parts = [p for p in path.split("/") if p]
        if not parts:
            return False
        parent = self._walk(parts[:-1])
        if not isinstance(parent, dict) or parts[-1] in parent:
            return False
        parent[parts[-1]] = value
        return True

    def mkdir(self, path: str) -> bool:
        return self._create(path, {})

    def addFile(self, path: str, size: int) -> bool:
        return self._create(path, size)

    def du(self, path: str) -> int:
        node = self._walk([p for p in path.split("/") if p])
        if node is None:
            return -1
        total, stack = 0, [node]
        while stack:
            cur = stack.pop()
            if isinstance(cur, dict):
                stack.extend(cur.values())
            else:
                total += cur
        return total

    def rm(self, path: str) -> bool:
        parts = [p for p in path.split("/") if p]
        if not parts:
            return False
        parent = self._walk(parts[:-1])
        if not isinstance(parent, dict) or parts[-1] not in parent:
            return False
        del parent[parts[-1]]
        return True

