class Solution:
    def findPath(self, grid: List[List[int]]) -> str:
        n, m = len(grid), len(grid[0])
        ok = [[False] * (m + 1) for _ in range(n + 1)]
        for r in range(n - 1, -1, -1):
            for c in range(m - 1, -1, -1):
                if grid[r][c] == 0:
                    ok[r][c] = (r == n - 1 and c == m - 1) or ok[r + 1][c] or ok[r][c + 1]
        if not ok[0][0]:
            return "NONE"
        r = c = 0
        moves = []
        while (r, c) != (n - 1, m - 1):
            if ok[r + 1][c]:
                moves.append("D")
                r += 1
            else:
                moves.append("R")
                c += 1
        return "".join(moves)

