class Solution:
    def fixedPoint(self, arr: List[int]) -> int:
        lo, hi = 0, len(arr)
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] >= mid:
                hi = mid
            else:
                lo = mid + 1
        return lo if lo < len(arr) and arr[lo] == lo else -1

