class Solution:
    def towerMoves(self, n: int) -> List[List[int]]:
        moves = []

        def shift(count, src, dst, spare):
            if count == 0:
                return
            shift(count - 1, src, spare, dst)
            moves.append([src, dst])
            shift(count - 1, spare, dst, src)
        shift(n, 0, 2, 1)
        return moves

