ctci-letter-orders.solution:
class Solution:
    def distinctOrders(self, s: str) -> List[str]:
        counts = collections.Counter(s)
        letters = sorted(counts)
        out, current = [], []

        def build():
            if len(current) == len(s):
                out.append("".join(current))
                return
            for ch in letters:
                if counts[ch]:
                    counts[ch] -= 1
                    current.append(ch)
                    build()
                    current.pop()
                    counts[ch] += 1
        build()
        return out

