        pass

ctci-bool-expr-ways.solution:
class Solution:
    def countWays(self, expr: str, want: bool) -> int:
        vals = [int(ch) for ch in expr[0::2]]
        ops = expr[1::2]
        n = len(vals)
        true = [[0] * n for _ in range(n)]
        false = [[0] * n for _ in range(n)]
        for i in range(n):
            true[i][i] = vals[i]
            false[i][i] = 1 - vals[i]
        for size in range(2, n + 1):
            for i in range(n - size + 1):
                j = i + size - 1
                t = f = 0
                for k in range(i, j):
                    lt, lf, rt, rf = true[i][k], false[i][k], true[k + 1][j], false[k + 1][j]
                    if ops[k] == "&":
                        t += lt * rt
                        f += lt * rf + lf * rt + lf * rf
                    elif ops[k] == "|":
                        t += lt * rt + lt * rf + lf * rt
                        f += lf * rf
                    else:
                        t += lt * rf + lf * rt
                        f += lt * rt + lf * rf
                true[i][j], false[i][j] = t, f
        return true[0][n - 1] if want else false[0][n - 1]

