        i, j, k = m - 1, len(b) - 1, m + len(b) - 1
        while j >= 0:
            if i >= 0 and a[i] > b[j]:
                a[k] = a[i]
                i -= 1
            else:
                a[k] = b[j]
                j -= 1
            k -= 1

