ctci-sparse-word-search.solution:
class Solution:
    def findWord(self, words: List[str], target: str) -> int:
        lo, hi = 0, len(words) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            left, right = mid, mid + 1
            probe = -1
            while left >= lo or right <= hi:
                if left >= lo and words[left]:
                    probe = left
                    break
                if right <= hi and words[right]:
                    probe = right
                    break
                left -= 1
                right += 1
            if probe == -1:
                return -1
            if words[probe] == target:
                return probe
            if words[probe] < target:
                lo = probe + 1
            else:
                hi = probe - 1
        return -1

