ctci-rank-board.solution:
class RankBoard:
    SIZE = 100001

    def __init__(self):
        self.tree = [0] * (self.SIZE + 1)

    def record(self, x: int) -> None:
        i = x + 1
        while i <= self.SIZE:
            self.tree[i] += 1
            i += i & -i

    def countAtMost(self, x: int) -> int:
        i = min(x, self.SIZE - 1) + 1
        total = 0
        while i > 0:
            total += self.tree[i]
            i -= i & -i
        return total

