class Solution:
    def locate(self, grid: List[List[int]], target: int) -> List[int]:
        if not grid or not grid[0]:
            return [-1, -1]
        r, c = 0, len(grid[0]) - 1
        while r < len(grid) and c >= 0:
            if grid[r][c] == target:
                return [r, c]
            if grid[r][c] > target:
                c -= 1
            else:
                r += 1
        return [-1, -1]

