class Solution:
    def uncoveredPairs(self, levels: List[int], tests: List[List[int]]) -> int:
        n = len(levels)
        total = sum(levels[i] * levels[j] for i in range(n) for j in range(i + 1, n))
        seen = set()
        for test in tests:
            for i in range(n):
                for j in range(i + 1, n):
                    seen.add((i, j, test[i], test[j]))
        return total - len(seen)

