ctci-tail-lines.solution:
class Solution:
    def lastLines(self, lines: List[str], k: int) -> List[str]:
        if k == 0:
            return []
        ring = [None] * k
        count = 0
        for line in lines:
            ring[count % k] = line
            count += 1
        if count <= k:
            return ring[:count]
        start = count % k
        return ring[start:] + ring[:start]

