        pass

ctci-lock-order-risk.solution:
class Solution:
    def canDeadlock(self, plans: List[List[int]]) -> bool:
        after = collections.defaultdict(set)
        nodes = set()
        for plan in plans:
            nodes.update(plan)
            for a, b in zip(plan, plan[1:]):
                after[a].add(b)
        indeg = {v: 0 for v in nodes}
        for a in after:
            for b in after[a]:
                indeg[b] += 1
        ready = [v for v in nodes if indeg[v] == 0]
        done = 0
        while ready:
            v = ready.pop()
            done += 1
            for w in after[v]:
                indeg[w] -= 1
                if indeg[w] == 0:
                    ready.append(w)
        return done != len(nodes)

