ctci-lost-update-replay.solution:
class Solution:
    def finalCount(self, schedule: List[int]) -> int:
        counter = 0
        step, local = {}, {}
        for t in schedule:
            s = step.get(t, 0)
            if s == 0:
                local[t] = counter
            elif s == 1:
                local[t] += 1
            else:
                counter = local[t]
            step[t] = (s + 1) % 3
        return counter

