        pass

ctci-rolling-hash-find.solution:
class Solution:
    def findAll(self, text: str, pattern: str) -> List[int]:
        n, m = len(text), len(pattern)
        if m == 0 or m > n:
            return []
        BASE, MOD = 257, (1 << 61) - 1
        top = pow(BASE, m - 1, MOD)
        want = have = 0
        for i in range(m):
            want = (want * BASE + ord(pattern[i])) % MOD
            have = (have * BASE + ord(text[i])) % MOD
        hits = []
        for start in range(n - m + 1):
            if have == want and text[start:start + m] == pattern:
                hits.append(start)
            if start + m < n:
                have = ((have - ord(text[start]) * top) * BASE + ord(text[start + m])) % MOD
        return hits

ctci-avl-insert-all.starter:
class Solution:
    def avlBuild(self, keys: List[int]) -> Optional[TreeNode]:
        pass

ctci-avl-insert-all.solution:
class Solution:
    def avlBuild(self, keys: List[int]) -> Optional[TreeNode]:
        def h(node):
            return node.height if node else 0

        def update(node):
            node.height = 1 + max(h(node.left), h(node.right))

        def rotate_right(y):
            x = y.left
            y.left, x.right = x.right, y
            update(y)
            update(x)
            return x

        def rotate_left(x):
            y = x.right
            x.right, y.left = y.left, x
            update(x)
            update(y)
            return y

        def insert(node, key):
            if node is None:
                fresh = TreeNode(key)
                fresh.height = 1
                return fresh
            if key < node.val:
                node.left = insert(node.left, key)
            else:
                node.right = insert(node.right, key)
            update(node)
            balance = h(node.left) - h(node.right)
            if balance > 1:
                if h(node.left.left) < h(node.left.right):
                    node.left = rotate_left(node.left)
                return rotate_right(node)
            if balance < -1:
                if h(node.right.right) < h(node.right.left):
                    node.right = rotate_right(node.right)
                return rotate_left(node)
            return node
        root = None
        for key in keys:
            root = insert(root, key)
        return root

ctci-tic-tac-winner.starter:
