ctci-smallest-gap-pair.solution:
class Solution:
    def smallestGap(self, a: List[int], b: List[int]) -> int:
        a, b = sorted(a), sorted(b)
        i = j = 0
        best = abs(a[0] - b[0])
        while i < len(a) and j < len(b):
            gap = a[i] - b[j]
            if abs(gap) < best:
                best = abs(gap)
            if gap == 0:
                return 0
            if gap < 0:
                i += 1
            else:
                j += 1
        return best

