        pass

ctci-pattern-ab-match.solution:
class Solution:
    def fits(self, pattern: str, text: str) -> bool:
        n = len(text)
        count_a, count_b = pattern.count("a"), pattern.count("b")
        first, other = ("a", "b") if pattern[0] == "a" else ("b", "a")
        c1 = count_a if first == "a" else count_b
        c2 = len(pattern) - c1
        for len1 in range(1, n // c1 + 1):
            rest = n - c1 * len1
            if c2 == 0:
                if rest != 0:
                    continue
                len2 = 0
            else:
                if rest <= 0 or rest % c2:
                    continue
                len2 = rest // c2
            word1 = text[:len1]
            word2 = None
            pos, ok = 0, True
            for ch in pattern:
                if ch == first:
                    if text[pos:pos + len1] != word1:
                        ok = False
                        break
                    pos += len1
                else:
                    piece = text[pos:pos + len2]
                    if word2 is None:
                        word2 = piece
                    elif piece != word2:
                        ok = False
                        break
                    pos += len2
            if ok:
                return True
        return False

ctci-blot-sizes.starter:
