        pass

ctci-blot-sizes.solution:
class Solution:
    def blotSizes(self, page: List[List[int]]) -> List[int]:
        rows, cols = len(page), len(page[0])
        seen = [[False] * cols for _ in range(rows)]
        sizes = []
        for r in range(rows):
            for c in range(cols):
                if page[r][c] != 0 or seen[r][c]:
                    continue
                seen[r][c] = True
                stack, size = [(r, c)], 0
                while stack:
                    y, x = stack.pop()
                    size += 1
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < rows and 0 <= nx < cols and page[ny][nx] == 0 and not seen[ny][nx]:
                                seen[ny][nx] = True
                                stack.append((ny, nx))
                sizes.append(size)
        return sorted(sizes)

