        pass

ctci-count-digit-occurrences.solution:
class Solution:
    def countDigit(self, n: int, d: int) -> int:
        total, power = 0, 1
        while power <= n:
            higher = n // (power * 10)
            current = n // power % 10
            lower = n % power
            total += higher * power
            if current > d:
                total += power
            elif current == d:
                total += lower + 1
            power *= 10
        return total

ctci-name-frequency-merge.starter:
class Solution:
    def mergeCounts(self, counts: List[List], aliases: List[List[str]]) -> List[List]:
        pass

ctci-name-frequency-merge.solution:
class Solution:
    def mergeCounts(self, counts: List[List], aliases: List[List[str]]) -> List[List]:
        parent = {}

        def find(x):
            parent.setdefault(x, x)
            root = x
            while parent[root] != root:
                root = parent[root]
            while parent[x] != root:
                parent[x], x = root, parent[x]
            return root
        for a, b in aliases:
            ra, rb = find(a), find(b)
            if ra != rb:
                if ra < rb:
                    parent[rb] = ra
                else:
                    parent[ra] = rb
        totals = collections.defaultdict(int)
        for name, number in counts:
            totals[find(name)] += number
        return [[label, totals[label]] for label in sorted(totals)]

