        pass

ctci-longest-compound-word.solution:
class Solution:
    def longestCompound(self, words: List[str]) -> str:
        known = set(words)

        def buildable(word):
            n = len(word)
            ok = [False] * (n + 1)
            ok[0] = True
            for end in range(1, n + 1):
                for start in range(end):
                    if ok[start] and (start > 0 or end < n) and word[start:end] in known:
                        ok[end] = True
                        break
            return ok[n]
        for word in sorted(words, key=lambda w: (-len(w), w)):
            if buildable(word):
                return word
        return ""

ctci-max-block-sum.starter:
