        pass

ctci-max-block-sum.solution:
class Solution:
    def bestBlock(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])
        best = grid[0][0]
        for top in range(rows):
            column_sum = [0] * cols
            for bottom in range(top, rows):
                row = grid[bottom]
                run = 0
                for c in range(cols):
                    column_sum[c] += row[c]
                    run = column_sum[c] if run <= 0 else run + column_sum[c]
                    if run > best:
                        best = run
        return best
